using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace Kotli.Generators;

[Generator]
public class ToolRouterGenerator : IIncrementalGenerator
{
    public void Initialize(IncrementalGeneratorInitializationContext context)
    {
        context.RegisterPostInitializationOutput(ctx =>
        {
            var source = """
// <auto-generated />
using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using System.Text.Json;
using Kotli.Domain.Interfaces;
using Kotli.Domain.Models;

namespace Kotli.Infrastructure.Tools;

public class ToolExecutionRouter : IToolExecutionRouter
{
    private readonly IReadTool _readTool;
    private readonly IWriteTool _writeTool;
    private readonly IWebSearchTool _webSearchTool;

    public ToolExecutionRouter(IReadTool readTool, IWriteTool writeTool, IWebSearchTool webSearchTool)
    {
        _readTool = readTool ?? throw new ArgumentNullException(nameof(readTool));
        _writeTool = writeTool ?? throw new ArgumentNullException(nameof(writeTool));
        _webSearchTool = webSearchTool ?? throw new ArgumentNullException(nameof(webSearchTool));
    }

    public async Task<ToolResponse> ExecuteToolAsync(ToolCall toolCall)
    {
        string result = "";
        try
        {
            switch (toolCall.Name)
            {
                case "read_file":
                    {
                        var args = JsonSerializer.Deserialize<ReadFileArgs>(toolCall.ArgumentsJson);
                        result = await _readTool.ReadFileAsync(args?.filePath ?? "", args?.startLine, args?.endLine);
                    }
                    break;
                case "list_directory":
                    {
                        var args = JsonSerializer.Deserialize<ListDirectoryArgs>(toolCall.ArgumentsJson);
                        result = await _readTool.ListDirectoryAsync(args?.dirPath ?? "");
                    }
                    break;
                case "write_file":
                    {
                        var args = JsonSerializer.Deserialize<WriteFileArgs>(toolCall.ArgumentsJson);
                        result = await _writeTool.WriteFileAsync(args?.filePath ?? "", args?.content ?? "");
                    }
                    break;
                case "replace_text":
                    {
                        var args = JsonSerializer.Deserialize<ReplaceTextArgs>(toolCall.ArgumentsJson);
                        result = await _writeTool.ReplaceTextAsync(args?.filePath ?? "", args?.oldString ?? "", args?.newString ?? "");
                    }
                    break;
                case "web_search":
                    {
                        var args = JsonSerializer.Deserialize<WebSearchArgs>(toolCall.ArgumentsJson);
                        result = await _webSearchTool.SearchAsync(args?.query ?? "");
                    }
                    break;
                default:
                    result = $"[Error] Unknown tool name: {toolCall.Name}";
                    break;
            }
        }
        catch (Exception ex)
        {
            result = $"[Error] Tool execution failed: {ex.Message}";
        }

        return new ToolResponse(toolCall.Id, result);
    }

    public IEnumerable<ToolDefinition> GetToolDefinitions()
    {
        yield return new ToolDefinition(
            "read_file",
            "Reads a specific section of a local file by line numbers. Use this instead of reading the whole file.",
            "{\"type\":\"object\",\"properties\":{\"filePath\":{\"type\":\"string\",\"description\":\"The path to the file to read\"},\"startLine\":{\"type\":\"integer\",\"description\":\"The 1-based start line (inclusive)\"},\"endLine\":{\"type\":\"integer\",\"description\":\"The 1-based end line (inclusive)\"}},\"required\":[\"filePath\"]}"
        );

        yield return new ToolDefinition(
            "list_directory",
            "Lists all subdirectories and files in a workspace directory.",
            "{\"type\":\"object\",\"properties\":{\"dirPath\":{\"type\":\"string\",\"description\":\"The path of the directory to list (relative to workspace root)\"}},\"required\":[\"dirPath\"]}"
        );

        yield return new ToolDefinition(
            "write_file",
            "Writes complete contents to a file. Overwrites existing files or creates new files.",
            "{\"type\":\"object\",\"properties\":{\"filePath\":{\"type\":\"string\",\"description\":\"The path to write the file to\"},\"content\":{\"type\":\"string\",\"description\":\"The complete text content of the file\"}},\"required\":[\"filePath\",\"content\"]}"
        );

        yield return new ToolDefinition(
            "replace_text",
            "Surgically replaces a unique substring inside an existing file. This is the preferred tool for modifications as it minimizes overhead.",
            "{\"type\":\"object\",\"properties\":{\"filePath\":{\"type\":\"string\",\"description\":\"The path of the file to modify\"},\"oldString\":{\"type\":\"string\",\"description\":\"The exact string to find and replace\"},\"newString\":{\"type\":\"string\",\"description\":\"The new string to insert\"}},\"required\":[\"filePath\",\"oldString\",\"newString\"]}"
        );

        yield return new ToolDefinition(
            "web_search",
            "Searches the web for up-to-date documentation or general information.",
            "{\"type\":\"object\",\"properties\":{\"query\":{\"type\":\"string\",\"description\":\"The search query\"}},\"required\":[\"query\"]}"
        );
    }

    private class ReadFileArgs { public string filePath { get; set; } = ""; public int? startLine { get; set; } public int? endLine { get; set; } }
    private class ListDirectoryArgs { public string dirPath { get; set; } = ""; }
    private class WriteFileArgs { public string filePath { get; set; } = ""; public string content { get; set; } = ""; }
    private class ReplaceTextArgs { public string filePath { get; set; } = ""; public string oldString { get; set; } = ""; public string newString { get; set; } = ""; }
    private class WebSearchArgs { public string query { get; set; } = ""; }
}
""";
            ctx.AddSource("ToolExecutionRouter.g.cs", SourceText.From(source, Encoding.UTF8));
        });
    }
}
